        "image": "https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fb/Sloop_Example.svg/500px-Sloop_Example.svg.png?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail"
